from pathlib import Path
import json
r=Path(__file__).parent
def read(s):return (r/'exemplo'/s).read_text()
def section(label,text,code='',language='python'):return dict(label=label,text=text,code=code,language=language)
prefix='https://docs.djangoproject.com/en/5.2/'
steps=[
('Model + migração','Defina a entidade e os campos; se o enunciado pedir, inclua relacionamento. Gere e aplique as migrações.','quartos/models.py', [section('O que desenvolver','A classe Quarto representa uma tabela; numero é único, tipo é texto e disponivel tem valor padrão.',read('quartos/models.py')),section('Comandos necessários','Execute na pasta que contém manage.py. O primeiro comando cria o arquivo de migração; o segundo aplica as alterações.','python manage.py makemigrations\npython manage.py migrate','bash'),section('Admin opcional','Para cadastrar dados no painel, registre o model em quartos/admin.py e crie um superusuário após migrar.',read('quartos/admin.py')),section('Como verificar','Execute python manage.py showmigrations e confirme [X] para a migração do app. Crie o usuário com python manage.py createsuperuser e acesse /admin/.')],prefix+'topics/migrations/','model'),
('URLs','Crie uma rota para a listagem e outra para o detalhe.','quartos/urls.py e resort/urls.py',[section('URLs do aplicativo','O conversor int captura pk; name permite gerar a URL sem fixar caminhos.', 'from django.urls import path\nfrom . import views\n\napp_name = "quartos"\nurlpatterns = [\n    path("quartos/", views.lista_quartos, name="lista"),\n    path("quartos/<int:pk>/", views.detalhe_quarto, name="detalhe"),\n]'),section('Conexão no projeto','O projeto inclui as rotas do app. A API será conectada na etapa 7.','from django.contrib import admin\nfrom django.urls import include, path\n\nurlpatterns = [\n    path("admin/", admin.site.urls),\n    path("", include("quartos.urls")),\n]'),section('Como verificar','Após criar as views e templates nas próximas etapas, abra /quartos/ e /quartos/1/. O detalhe retorna 404 se o quarto não existir.')],prefix+'topics/http/urls/','path'),
('Views','Implemente listagem e detalhe usando get_object_or_404 para um objeto ausente.','quartos/views.py',[section('Como funciona','A view de listagem envia a chave quartos ao template; a de detalhe recebe pk da rota. A rota de cadastro será adicionada na etapa 6.', 'from django.shortcuts import get_object_or_404, render\nfrom .models import Quarto\n\ndef lista_quartos(request):\n    quartos = Quarto.objects.filter(disponivel=True).order_by("numero")\n    return render(request, "quartos/lista.html", {"quartos": quartos})\n\ndef detalhe_quarto(request, pk):\n    quarto = get_object_or_404(Quarto, pk=pk)\n    return render(request, "quartos/detalhe.html", {"quarto": quarto})'),section('Como verificar','Registre o model no admin e crie um superusuário como na etapa 1; após criar os templates na etapa 5, visite a lista e o detalhe. Um pk inexistente deve responder 404.')],prefix+'topics/http/views/','view'),
('ORM','Faça uma consulta com .filter() dentro da view.','quartos/views.py',[section('Consulta com filtro','Aqui somente quartos disponíveis chegam à lista. filter retorna um QuerySet, mesmo quando não há resultados; order_by ordena pelo número.','quartos = Quarto.objects.filter(disponivel=True).order_by("numero")'),section('Como verificar','Crie um quarto disponível e outro indisponível. Apenas o primeiro deve aparecer na listagem; o detalhe ainda pode ser acessado pelo seu id.')],prefix+'topics/db/queries/','filter'),
('Template','Apresente os dados da view em HTML usando {% for %}.','quartos/templates/quartos/lista.html',[section('Listagem HTML','A view envia {"quartos": quartos}; o for usa exatamente quartos. empty cobre lista vazia.','\n'.join(line for line in read('quartos/templates/quartos/lista.html').splitlines() if 'Cadastrar quarto' not in line),'html'),section('Template de detalhe','A view também precisa deste arquivo para a rota de detalhe.',read('quartos/templates/quartos/detalhe.html'),'html'),section('Como verificar','Abra /quartos/. Se faltarem dados, confira filtro, registros e nome do contexto. Uma lista vazia não é, por si só, prova de falta de migração.')],prefix+'topics/templates/','for'),
('Forms + validação','Crie ModelForm e validação customizada clean_campo.','quartos/forms.py e quartos/templates/quartos/form.html',[section('Formulário','clean_numero devolve o valor validado ou lança ValidationError. A regra vale ao validar este formulário; não é aplicada automaticamente por save() nem pelo serializer.',read('quartos/forms.py')),section('View completa de cadastro','Atualize views.py para incluir QuartoForm e criar_quarto. Reative a rota quartos/novo/ da etapa 2.',read('quartos/views.py')),section('URL completa','Adicione a rota de cadastro e mantenha as rotas anteriores.',read('quartos/urls.py')),section('HTML e CSRF',"O formulário envia POST com proteção CSRF. Opcional: adicione na lista um link com {% url 'quartos:criar' %}.",read('quartos/templates/quartos/form.html'),'html'),section('Como verificar','Acesse /quartos/novo/, tente número 0 e observe o erro; depois envie um número positivo único. O modelo também tem unique=True.')],prefix+'ref/forms/validation/','modelform'),
('API REST','Exponha serializer, viewset e router e apresente GET e POST com JSON.','quartos/api.py e resort/urls.py',[section('Serializer e ViewSet','ModelSerializer transforma e valida os dados da API; ModelViewSet fornece operações. A validação específica do Form não é automaticamente compartilhada com a API.',read('quartos/api.py')),section('Router','Atualize o arquivo do projeto. DefaultRouter gera a rota /api/quartos/.',read('resort/urls.py')),section('Requisições de exemplo','Com o servidor ativo, GET devolve a lista; POST cria um quarto e, se válido, retorna 201. O id gerado pode variar.','curl http://127.0.0.1:8000/api/quartos/\ncurl -i -X POST http://127.0.0.1:8000/api/quartos/ -H "Content-Type: application/json" -d \'{"numero":102,"tipo":"Luxo","disponivel":true}\'\n# 201 Created: {"id": 1, "numero": 102, "tipo": "Luxo", "disponivel": true}','bash'),section('Como verificar','Confira GET /api/quartos/ e a resposta 201 do POST. Salve os prints solicitados. Este exemplo é local e não configura segurança para produção.')],'https://www.django-rest-framework.org/tutorial/quickstart/','drf'),
('Testes com pytest','Escreva teste(s) passando; o diagrama pede um ou mais, enquanto este guia exercita Model, View e API.','pytest.ini e quartos/tests/test_quartos.py',[section('Configuração','Instale pytest e pytest-django no ambiente; configure o settings module.',read('pytest.ini'),'ini'),section('Testes integrados','Cada teste que usa banco solicita django_db. client faz requisições sem servidor e cada assert verifica o resultado.',read('quartos/tests/test_quartos.py')),section('Executar e verificar','Execute pytest; confirme três testes passando e capture o resultado para a entrega.','pytest -v','bash')],'https://pytest-django.readthedocs.io/en/latest/tutorial.html','pytest')]
